// Compile gate: the whole file must be valid or nothing runs.
function develop(lines, brokenIdx) {
  const broken = brokenIdx >= 0 ? [brokenIdx] : [];
  if (broken.length > 0) return 'error hello.go:' + (broken[0] + 1) + ' (nothing ran)';
  return lines.join('|');
}
console.log('all-valid: ' + develop(['hi', 'ho', 'hu'], -1));
console.log('line3-broken: ' + develop(['hi', 'ho', 'hu'], 2));
